package android.widget;public class LinearLayout extends android.view.View {public static final int HORIZONTAL=0,VERTICAL=1;public int orientation;public java.util.List<android.view.View> children=new java.util.ArrayList<>();public LinearLayout(android.content.Context c){super(c);}public void setOrientation(int n){orientation=n;}public void setGravity(int g){}public void addView(android.view.View v){children.add(v);}public void addView(android.view.View v,LayoutParams p){v.params=p;children.add(v);}public static class LayoutParams{public int width,height,leftMargin;public float weight;public LayoutParams(int w,int h){width=w;height=h;}public LayoutParams(int w,int h,float x){this(w,h);weight=x;}}}
